import React, {useState } from 'react';
import './addSupplierForm.css'

function AddSupplierForm({addSupplier}) {
    // Declare a state variable to store information about the supplier
    // With an initial empty string value "set..."
    // to update the information state
    const [name, setCompanyName] = useState("");
    const [contact, setContact] = useState("");
    const [website, setWebsite] = useState("");
    const [phone, setPhone] = useState("");
    const [email, setEmail] = useState("");
    const [street, setStreet] = useState("");
    const [city, setCity] = useState("");
    const [postalCode, setPostalCode] = useState("");
    const [country, setCountry] = useState("");
    const [notes, setNotes] = useState("");

    // Handle input change and automatically add http:// if missing
    const handleWebsiteChange = (e) => {
        let inputValue = e.target.value;
        if (inputValue && !inputValue.startsWith("http://") && !inputValue.startsWith("https://")) {
            if (inputValue.startsWith("www")) {
                // Add "http//" if "www" is at the beginning
                inputValue = "http://" + inputValue;
            }
        }
        // Update 
        setWebsite(inputValue);
    };

    // Handle the form submission
    const handleSubmit = (e) => {
        e.preventDefault();

        // Checking if all the fields are filled
        const requiredFields = [
            name, contact, website, phone, email, street, city, postalCode, country
        ];

        if (requiredFields.some(field => !field)) {
            
            alert("Please fill in all fields");
            return;

        }

        // Creating a object for the new supplier
        const newSupplier = {
            name,
            contact,
            website,
            phone,
            email,
            street,
            city,
            postalCode,
            country,
            notes,
        };

        alert(newSupplier.name + " " + newSupplier.contact + " " + newSupplier.website + " " + newSupplier.phone + " " + newSupplier.email + " " + newSupplier.street + " " + newSupplier.city + " " + newSupplier.postalCode + " " + newSupplier.country + " " + newSupplier.notes);

        // calling function onAddSupplier
        addSupplier(newSupplier);
        // Clear the field
        setCompanyName("");
        setContact("");
        setWebsite("");
        setPhone("");
        setEmail("");
        setStreet("");
        setCity("");
        setPostalCode("");
        setCountry("");
        setNotes("");

    };

    return (
        <form onSubmit={handleSubmit}>

            <h1> Add a New Supplier</h1>

            <div className='twoFieldsHolder'>

                <div className='formField'>
                    <label>Company Name: </label>
                    <input
                        type="text"
                        value={name}
                        onChange={(e) => setCompanyName(e.target.value)}
                        className='shortInputField'
                    />
                </div>

                <div className='formField'>
                    <label>Contact Person: </label>
                    <input
                        type="text"
                        value={contact}
                        onChange={(e) => setContact(e.target.value)}
                        className='longInputField'
                    />
                </div>

            </div>

            <div className='twoFieldsHolder'>

                <div className='formField'>
                    <label>Website: </label>
                    <input
                        type="url"
                        value={website}
                        onChange={handleWebsiteChange} // using the custom handle function 
                        placeholder="www.example.com"
                        required
                        className='longInputField'
                    />
                </div>
                <div className='formField'>
                    <label>Phone Number: </label>
                    <input 
                        type="tel"
                        value={phone}
                        onChange={(e) => setPhone(e.target.value)}
                        className='shortInputField'
                    />
                </div>

            </div>
            
            <div className='formField'>
                <label>Email: </label>
                <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className='longInputField'
                />
            </div>

            <div className='formField'>
                <label>Street: </label>
                <input
                    type="text"
                    value={street}
                    onChange={(e) => setStreet(e.target.value)}
                    className='longInputField'
                />
            </div>

            <div className='twoFieldsHolder'>

                <div className='formField'>
                    <label>City: </label>
                    <input
                        type="text"
                        value={city}
                        onChange={(e) => setCity(e.target.value)}
                        className='shortInputField'
                    />
                </div>
                 <div className='formField'>
                    <label>Postal Code: </label>
                    <input
                        type="text"
                        value={postalCode}
                        onChange={(e) => setPostalCode(e.target.value)}
                        className='shortInputField'
                    />
                </div>

            </div>

            <div className='formField'>
                <label>Country: </label>
                <input
                    type="text"
                    value={country}
                    onChange={(e) => setCountry(e.target.value)}
                    className='shortInputField'
                />
            </div>
            
            <div className='formField'>
                <label>Additional Notes: </label>
                <textarea
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    className='longInputField'
                />
            </div>
            <button className='addBtn' type="submit">Add Supplier</button>
        </form>
    );
}

export default AddSupplierForm;
